/*
 * MONSTRIX Emotional Robot v2.0 - New Library v1.1.1
 * ESP32-C3 + OLED 0.96" + GY-273 (HMC5883L) + FluxGarage_RoboEyes v1.1.1
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <FluxGarage_RoboEyes.h>
#include <HMC5883L.h>

// Display configuration
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDR 0x3C

// I2C pins for display
#define DISPLAY_SDA 8
#define DISPLAY_SCK 9

// I2C pins for magnetometer
#define COMPASS_SDA 4
#define COMPASS_SCK 5

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
RoboEyes<Adafruit_SSD1306> eyes(display);
HMC5883L compass;

// Timing variables
unsigned long lastEmotionChange = 0;
unsigned long lastAngryTime = 0;
unsigned long lastSweatTime = 0;
const int EMOTION_INTERVAL = 6000;
const int ANGRY_DURATION = 3000;
const int SWEAT_DURATION = 5000;
bool isAngry = false;
bool isSweating = false;

// Переменные для магнитометра
int prevX = 0, prevY = 0, prevZ = 0;
unsigned long lastCompassRead = 0;
float movementThreshold = 50.0; // Порог изменения для обнаружения движения

void setup() {
  Serial.begin(115200);

  Serial.println("MONSTRIX Robot v2.0 Starting...");

  // Инициализация I2C для дисплея на пинах 8 (SDA) и 9 (SCK)
  Wire.begin(DISPLAY_SDA, DISPLAY_SCK);

  if(!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("SSD1306 allocation failed");
    return;
  }

  display.setRotation(0);
  display.clearDisplay();
  display.display();
  Serial.println("Display initialized");

  eyes.begin(SCREEN_WIDTH, SCREEN_HEIGHT, 60);
  eyes.setAutoblinker(ON, 3, 1);
  eyes.setIdleMode(ON, 2, 1);
  eyes.setMood(DEFAULT);
  eyes.setDisplayColors(0, 1);

  Serial.println("RoboEyes initialized!");

  // Инициализация GY-273 на пинах 4 (SDA) и 5 (SCK)
  Serial.println("Initializing GY-273...");

  // Переключаем I2C на пины магнитометра
  Wire.end();
  Wire.begin(COMPASS_SDA, COMPASS_SCK);

  if (!compass.begin()) {
    Serial.println("GY-273 not found. Check connections!");
    Serial.println("Continuing without motion detection...");
  } else {
    Serial.println("GY-273 connected!");

    // Просто читаем начальные значения
    Vector raw = compass.readRaw();
    prevX = raw.XAxis;
    prevY = raw.YAxis;
    prevZ = raw.ZAxis;

    Serial.println("Motion detection ready!");
  }

  Serial.println("MONSTRIX Robot Ready!");
}

void loop() {
  eyes.update();
  delay(16);

  unsigned long now = millis();

  // Читаем данные с GY-273
  if (!isAngry && (now - lastCompassRead > 100)) {

    // Переключаем I2C на магнитометр
    Wire.end();
    Wire.begin(COMPASS_SDA, COMPASS_SCK);

    Vector raw = compass.readRaw();

    // Вычисляем изменение по всем осям
    int diffX = abs(raw.XAxis - prevX);
    int diffY = abs(raw.YAxis - prevY);
    int diffZ = abs(raw.ZAxis - prevZ);

    // Суммарное изменение
    float totalDiff = diffX + diffY + diffZ;

    // Если изменение значительное - значит было движение
    if (totalDiff > movementThreshold) {
      Serial.print("Movement detected! Change: ");
      Serial.println(totalDiff);
      Serial.println("Getting angry... 😠");

      // Переключаем I2C обратно на дисплей для обновления глаз
      Wire.end();
      Wire.begin(DISPLAY_SDA, DISPLAY_SCK);

      eyes.setMood(ANGRY);
      eyes.setSweat(ON);

      isSweating = true;
      lastSweatTime = now;
      isAngry = true;
      lastAngryTime = now;
    }

    // Сохраняем текущие значения
    prevX = raw.XAxis;
    prevY = raw.YAxis;
    prevZ = raw.ZAxis;

    lastCompassRead = now;
  }

  // Stop sweating
  if (isSweating && (now - lastSweatTime > SWEAT_DURATION)) {
    // Переключаем I2C на дисплей
    Wire.end();
    Wire.begin(DISPLAY_SDA, DISPLAY_SCK);

    eyes.setSweat(OFF);
    isSweating = false;
    Serial.println("Stopped sweating");
  }

  // Anger timeout
  if (isAngry && (now - lastAngryTime > ANGRY_DURATION)) {
    Serial.println("Calming down... 😌");
    isAngry = false;
    lastEmotionChange = now;

    // Переключаем I2C на дисплей
    Wire.end();
    Wire.begin(DISPLAY_SDA, DISPLAY_SCK);

    setRandomMood();
    return;
  }

  // Auto emotion change
  if (!isAngry && (now - lastEmotionChange > EMOTION_INTERVAL)) {
    lastEmotionChange = now;
    setRandomMood();
  }
}

void setRandomMood() {
  int mood = random(0, 6);
  String moodName;

  // Убеждаемся, что I2C направлен на дисплей
  Wire.end();
  Wire.begin(DISPLAY_SDA, DISPLAY_SCK);

  switch (mood) {
    case 0: 
      eyes.setMood(DEFAULT); 
      moodName = "Default";
      break;
    case 1: 
      eyes.setMood(HAPPY); 
      moodName = "Happy";
      break;
    case 2: 
      eyes.setMood(TIRED); 
      moodName = "Tired";
      break;
    case 3: 
      eyes.anim_confused(); 
      moodName = "Confused";
      break;
    case 4:
      eyes.setMood(DEFAULT);
      if (random(0, 4) == 0) {
        eyes.setSweat(ON);
        isSweating = true;
        lastSweatTime = millis();
        moodName = "Stressed (sweating)";
      } else {
        moodName = "Calm";
      }
      break;
    case 5:
      eyes.anim_laugh();
      moodName = "Laughing";
      break;
  }

  Serial.print("New emotion: ");
  Serial.println(moodName);
}
